package com.sumedha.commerce.product.service; import com.sumedha.commerce.product.dto.request.*; import com.sumedha.commerce.product.dto.response.*; import com.sumedha.commerce.product.entity.Product; import com.sumedha.commerce.product.entity.ProductAttribute; import com.sumedha.commerce.product.mapper.ProductMapper; import com.sumedha.commerce.product.repository.ProductAttributeRepository; import com.sumedha.commerce.product.repository.ProductRepository; import com.sumedha.commerce.common.core.exception.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ProductAttributeServiceImpl implements ProductAttributeService {private final ProductRepository products;private final ProductAttributeRepository attributes;public ProductAttributeServiceImpl(ProductRepository p,ProductAttributeRepository a){products=p;attributes=a;}
@Transactional public ProductAttributeResponse create(UUID productId,CreateProductAttributeRequest r){product(productId);ProductAttribute attr=attributes.save(new ProductAttribute(productId,r.name(),r.value()));return ProductMapper.toAttributeResponse(attr);}
@Transactional(readOnly=true) public List<ProductAttributeResponse> list(UUID productId){product(productId);return attributes.findByProductId(productId).stream().map(ProductMapper::toAttributeResponse).toList();}
@Transactional public void delete(UUID productId,UUID attributeId){product(productId);ProductAttribute attr=attribute(productId,attributeId);attributes.delete(attr);}
private Product product(UUID id){return products.findById(id).orElseThrow(()->new ResourceNotFoundException("Product not found"));}
private ProductAttribute attribute(UUID productId,UUID attributeId){return attributes.findByIdAndProductId(attributeId,productId).orElseThrow(()->new ResourceNotFoundException("Product attribute not found"));}
}
